
.panel {
  min-height: 160px;
  height: 100%;
  padding: 10px 14px 12px 34px;
  background-image:
    radial-gradient(circle at 12px 50%, #7a5a3a 0 4px, transparent 4.5px),
    var(--img-grain),
    repeating-linear-gradient(transparent 0 31px, var(--c-rule) 31px 32px);
  background-size: 24px 26px, auto, auto;
  background-repeat: repeat-y, repeat, repeat;
  background-position: 0 6px, 0 0, 0 8px;
  border-radius: 0 3px 3px 3px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  overflow: auto;
}
h3 {
  font-size: 18px;
  margin-bottom: 4px;
}
h3 i {
  font-size: 0.8em;
}
ul {
  list-style: none;
}
li {
  display: grid;
  grid-template-columns: 52px 1fr 20px;
  gap: 8px;
  align-items: center;
  min-height: 32px;
  font-family: var(--font-hand);
  font-size: 14px;
}
li small {
  color: var(--c-text-muted);
  font-size: 12px;
}
li.done .content {
  text-decoration: line-through;
  text-decoration-color: rgba(58, 42, 31, 0.6);
  color: var(--c-text-muted);
}
.time {
  font-family: var(--font-latin);
  font-weight: 700;
}
.mark {
  font-size: 16px;
  color: var(--c-primary);
}
.empty {
  font-family: var(--font-hand);
  color: var(--c-text-muted);
  line-height: 32px;
}
.empty.blank {
  line-height: 1.4;
  min-height: 1.4em;
  padding: 4px 0;
}
.cards {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 8px;
  padding-right: 4px;
}
.card {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border: none;
  background: rgba(239, 226, 198, 0.55);
  padding: 7px 10px;
  border-radius: 3px;
  font-family: var(--font-hand);
  font-size: 13.5px;
  color: var(--c-text);
  box-shadow: 1px 1px 0 rgba(60, 40, 20, 0.12);
  cursor: pointer;
  text-align: left;
}
.card.open {
  background: var(--c-primary);
  color: var(--c-primary-ink);
}
.card .chev {
  font-size: 12px;
  opacity: 0.85;
}
.sheet {
  padding: 8px 10px 10px 8px;
  font-family: var(--font-hand);
  font-size: 13px;
  margin-bottom: 2px;
}
.day {
  margin-bottom: 6px;
}
.day ul {
  list-style: none;
  padding-left: 4px;
}
.day li,
.sheet > ul li {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 8px;
  align-items: baseline;
  min-height: 28px;
  grid-template-columns: none;
}
.t {
  font-family: var(--font-latin);
  font-weight: 700;
  min-width: 42px;
}
.job {
  margin-bottom: 4px;
}
