
.panel {
  min-height: 160px;
  height: 100%;
  padding: 10px 12px 12px;
  border-radius: 0 3px 3px 3px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
h3 {
  font-size: 18px;
}
h3 i {
  font-size: 0.8em;
}
.items {
  list-style: none;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 8px 12px;
}
li {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.label {
  align-self: flex-start;
  position: relative;
  font-family: var(--font-hand);
  font-size: 13.5px;
  font-weight: 700;
  background: #efe2c6;
  padding: 1px 10px 1px 16px;
  border-radius: 2px 10px 10px 2px;
  border: none;
  color: var(--c-text);
  box-shadow: 1px 1px 0 rgba(90, 65, 40, 0.25);
  cursor: pointer;
}
.label::before {
  content: '';
  position: absolute;
  left: 5px;
  top: 50%;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  translate: 0 -50%;
  background: var(--c-surface-paper);
  box-shadow: inset 0 0 0 1px rgba(90, 65, 40, 0.5);
}
.label b {
  margin-left: 6px;
  font-family: var(--font-latin);
  color: var(--c-text-muted);
  font-size: 12px;
}
.items p {
  font-family: var(--font-hand);
  font-size: 12px;
  color: var(--c-text-muted);
  padding-left: 4px;
}
.tools {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.sheet {
  padding: 8px 10px 10px 28px;
  font-family: var(--font-hand);
  font-size: 13px;
}
.sheet h4 {
  font-size: 15px;
  margin-bottom: 4px;
}
.day {
  margin-bottom: 6px;
}
.day ul {
  list-style: none;
  padding-left: 4px;
}
.day li,
.sheet > ul li {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 8px;
  align-items: baseline;
  min-height: 28px;
}
.t {
  font-family: var(--font-latin);
  font-weight: 700;
  min-width: 42px;
}
small {
  color: var(--c-text-muted);
  font-size: 11.5px;
}
.job {
  margin-bottom: 4px;
}
.phone {
  position: relative;
  padding: 10px 12px;
}
.phone .x {
  position: absolute;
  right: 8px;
  top: 4px;
  border: none;
  background: transparent;
  font-size: 18px;
}
.phone ul.contacts {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0;
}
.phone li {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  align-items: center;
  font-family: var(--font-hand);
  font-size: 12.5px;
  padding: 5px 0;
  border-bottom: 1px solid rgba(90, 70, 40, 0.22);
}
.phone li:last-child {
  border-bottom: none;
}
.cname {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.acts {
  display: flex;
  gap: 4px;
}
.ym-sticker.tiny {
  padding: 2px 8px;
  font-size: 12px;
}
.empty {
  font-family: var(--font-hand);
  color: var(--c-text-muted);
}
