
.panel {
  min-height: 160px;
  height: 100%;
  padding: 10px 12px 14px;
  border-radius: 0 3px 3px 3px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  overflow: hidden;
}
.scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
h3 {
  font-size: 18px;
}
h3 i {
  font-size: 0.8em;
}
.codex-title .count {
  margin-left: 6px;
  font-family: var(--font-latin);
  font-size: 12px;
  font-weight: 600;
  color: var(--c-text-muted);
}
.hint {
  font-family: var(--font-hand);
  font-size: 11.5px;
  color: var(--c-text-muted);
  margin: -2px 0 2px;
}
.sep {
  height: 0;
  border: none;
  border-top: 1px dashed rgba(90, 70, 40, 0.35);
  margin: 6px 0 4px;
}
.list {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.row {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  align-items: center;
  text-align: left;
  border: none;
  background: rgba(239, 226, 198, 0.45);
  padding: 6px 10px;
  font-family: var(--font-hand);
  font-size: 13.5px;
  color: var(--c-text);
  border-radius: 3px;
  box-shadow: 1px 1px 0 rgba(60, 40, 20, 0.12);
}
.row.dim {
  background: rgba(220, 210, 190, 0.35);
  color: var(--c-text-muted);
}
.row.on {
  background: var(--c-primary);
  color: var(--c-primary-ink);
}
.row.on .heart,
.row.on .badge {
  color: #fff;
}
.name {
  font-weight: 700;
}
.heart {
  font-family: var(--font-latin);
  font-size: 12px;
  color: #c0505a;
  white-space: nowrap;
}
.badge {
  font-size: 11px;
  white-space: nowrap;
  opacity: 0.85;
}
.badge-inline {
  display: inline-block;
  margin-bottom: 4px;
  padding: 1px 8px;
  border-radius: 999px;
  font-family: var(--font-hand);
  font-size: 11px;
  background: rgba(90, 70, 40, 0.12);
  color: var(--c-text-muted);
}
.detail {
  position: relative;
  padding: 10px 12px 12px;
  rotate: -0.5deg;
  flex-shrink: 0;
  max-height: 46%;
  overflow-y: auto;
}
.detail h4 {
  font-size: 18px;
  margin-bottom: 4px;
}
.detail .x {
  position: absolute;
  right: 8px;
  top: 4px;
  border: none;
  background: transparent;
  font-size: 18px;
  color: var(--c-text-muted);
}
.line {
  font-family: var(--font-hand);
  font-size: 12.5px;
  line-height: 1.55;
}
.line b {
  display: inline-block;
  min-width: 2.6em;
  margin-right: 6px;
  color: var(--c-text-muted);
  font-weight: 700;
}
.line.muted {
  color: var(--c-text-muted);
  font-size: 11.5px;
}
.promises {
  margin-top: 4px;
  padding-left: 14px;
  font-family: var(--font-hand);
  font-size: 11.5px;
}
.empty {
  font-family: var(--font-hand);
  color: var(--c-text-muted);
}
.field-intent {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 4px 0 6px;
}
.field-intent > span {
  font-family: var(--font-hand);
  font-size: 12px;
  color: var(--c-text-muted);
  font-weight: 700;
}
.pills {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.pill {
  border: none;
  background: rgba(220, 210, 190, 0.55);
  padding: 3px 10px;
  border-radius: 999px;
  font-family: var(--font-hand);
  font-size: 12.5px;
  color: var(--c-text);
  cursor: pointer;
}
.pill.on {
  background: var(--c-primary);
  color: var(--c-primary-ink);
}
