
.status-root {
  width: 100%;
  max-width: 720px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 4px 2px;
}

.body {
  border-radius: 6px;
  padding: 12px 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.identity {
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr);
  gap: 12px;
  align-items: start;
}
@media (max-width: 520px) {
  .identity {
    grid-template-columns: 1fr;
  }
}

.tabs {
  display: flex;
  gap: 4px;
  padding-left: 8px;
}
.tab {
  position: relative;
  border: none;
  border-radius: 8px 8px 0 0;
  background: rgba(239, 226, 198, 0.65);
  padding: 5px 14px 4px;
  font-family: var(--font-hand);
  font-size: 13px;
  font-weight: 700;
  color: var(--c-text-muted);
  translate: 0 3px;
  transition: translate 0.15s ease;
}
.tab i {
  font-size: 11px;
  margin-right: 2px;
}
.tab:hover {
  translate: 0 0;
}
.tab.on {
  background: var(--c-surface-paper);
  color: var(--c-text);
  translate: 0 1px;
}

.panel-stage {
  width: 100%;
  aspect-ratio: 16 / 10;
  min-height: 180px;
  max-height: 420px;
  overflow: hidden;
}
.panel-stage > * {
  height: 100%;
  overflow: auto;
  overscroll-behavior: contain;
}

.footer {
  display: flex;
  justify-content: center;
}
.collapse {
  position: relative;
  font-family: var(--font-hand);
  font-size: 13px;
  font-weight: 700;
  color: var(--c-text);
  background-color: var(--c-surface-paper-warm);
  background-image: var(--img-grain);
  border: none;
  padding: 4px 18px;
  box-shadow: var(--shadow-paper);
  rotate: -1deg;
}
