
.map-panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.head {
  display: flex;
  gap: 8px;
  align-items: center;
  justify-content: space-between;
}
.head h3 {
  font-size: 22px;
}
.head h3 i {
  font-size: 0.75em;
}
.back {
  padding: 4px 12px;
  font-size: 13px;
}

.tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}
.tab {
  font-family: var(--font-hand);
  font-size: 13px;
  font-weight: 700;
  color: var(--c-text);
  background-color: var(--c-surface-paper-warm);
  background-image: var(--img-grain);
  border: none;
  border-radius: 6px 6px 2px 2px;
  padding: 4px 12px;
  box-shadow: 1px 2px 0 rgba(60, 40, 20, 0.2);
}
.tab i {
  font-size: 11px;
}
.tab.on {
  background-color: var(--c-primary);
  color: var(--c-primary-ink);
}

.map-stage {
  width: 100%;
  max-width: 480px;
  margin: 0 auto;
  padding: 7px;
  rotate: -0.4deg;
}
.map {
  position: relative;
  width: 100%;
  max-width: 460px;
  margin: 0 auto;
  aspect-ratio: 942 / 1670;
  background: #d9c7a8 center / 100% 100% no-repeat;
}
.travel-map {
  background:
    linear-gradient(180deg, rgba(246, 238, 220, 0.92), rgba(232, 220, 196, 0.95)),
    #d9c7a8;
  overflow: hidden;
}
.travel-scroll {
  position: absolute;
  inset: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 14px 12px 18px;
  scrollbar-width: thin;
}
.sec-title {
  font-family: var(--font-title);
  font-size: 16px;
  margin: 4px 0 8px;
  color: var(--c-text);
}
.sec-title i {
  margin-right: 4px;
  color: var(--c-primary);
}
.sep {
  height: 0;
  border-top: 1.5px dashed rgba(90, 65, 40, 0.35);
  margin: 12px 0;
}
.travel-scroll ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.travel-scroll li {
  display: grid;
  grid-template-columns: 18px auto 1fr auto;
  gap: 6px;
  align-items: center;
  font-family: var(--font-hand);
  font-size: 13px;
  background: rgba(255, 250, 240, 0.75);
  padding: 4px 6px;
  border-radius: 4px;
}
.travel-scroll li span {
  color: var(--c-text-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.go-sm {
  padding: 2px 10px;
  font-size: 12px;
}
.empty {
  font-family: var(--font-hand);
  color: var(--c-text-muted);
  margin-bottom: 6px;
}

.pin {
  position: absolute;
  translate: -50% -100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  background: transparent;
  border: none;
  animation: ym-float 3s ease-in-out infinite;
  animation-delay: var(--d, 0s);
  z-index: 1;
}
.pin:hover,
.pin.on {
  z-index: 3;
}
.dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #fff8, transparent 45%), var(--pc, #c0392b);
  box-shadow: 0 2px 3px rgba(0, 0, 0, 0.4);
  position: relative;
}
.dot::after {
  content: '';
  position: absolute;
  left: 50%;
  top: 11px;
  width: 1.5px;
  height: 7px;
  translate: -50% 0;
  background: #555;
}
.label {
  order: -1;
  margin-bottom: 2px;
  display: flex;
  flex-direction: column;
  align-items: center;
  font-family: var(--font-hand);
  font-size: 12px;
  font-weight: 700;
  line-height: 1.2;
  white-space: nowrap;
  color: var(--c-text);
  background: rgba(246, 238, 220, 0.94);
  padding: 1px 6px;
  box-shadow: 1px 2px 3px rgba(40, 28, 18, 0.35);
  transition: transform 0.15s ease;
}
.label em {
  font-style: normal;
  font-size: 10px;
  color: var(--c-danger);
}
.pin:hover .label {
  transform: scale(1.08);
}
.pin.here .dot {
  box-shadow: 0 0 0 4px rgba(192, 57, 43, 0.35), 0 2px 3px rgba(0, 0, 0, 0.4);
}
.pin.on .label {
  background: var(--c-primary);
  color: var(--c-primary-ink);
}

.info {
  position: absolute;
  z-index: 5;
  left: 6%;
  right: 6%;
  bottom: 3%;
  padding: 12px 12px 10px;
  rotate: -1deg;
  box-shadow: var(--shadow-lift);
}
.info h4 {
  font-size: 20px;
}
.info p {
  font-family: var(--font-hand);
  font-size: 13px;
  margin: 2px 0 8px;
}
.info .x {
  position: absolute;
  right: 8px;
  top: 4px;
  border: none;
  background: transparent;
  font-size: 18px;
  color: var(--c-text-muted);
}
.go {
  padding: 6px 14px;
  font-size: 14px;
}

.hint {
  align-self: center;
  font-family: var(--font-hand);
  font-size: 12.5px;
  background: var(--c-surface-paper-warm);
  padding: 3px 14px;
  box-shadow: var(--shadow-paper);
  rotate: 0.5deg;
}
